with exploded as (select id, customer_id, created_at, coupon_codes, key, value from carts lateral view explode(attributes) e as key, value) select date_trunc('day', created_at) as activity_day, key, count(distinct key) as distinct_keys, count(distinct id) as distinct_ids, count(*) as cnt, count(distinct key) as distinct_keys_2, count(distinct key) as distinct_keys_3 from exploded group by rollup (date_trunc('day', created_at), key) order by activity_day desc;
